        size_t L = strlen(ent->d_name);
        if (L < 5 || strcmp(ent->d_name + L - 4, ".evd") != 0) continue;
        char path[512];
        snprintf(path, sizeof(path), "/app/rivetbay/evd/%s", ent->d_name);
